export type Lang = 'en' | 'pt';
export type Loc = Record<Lang, string>;
export type CategoryId = 'crypto' | 'encoding' | 'math' | 'lottery' | 'text';

export interface Tool {
  id: string;
  category: CategoryId;
  icon: string;
  name: Loc;
  blurb: Loc;
  inputs: ToolInput[];
  run: (values: Record<string, string>, ctx: ToolContext) => string | Promise<string>;
  /** Optional live visual (e.g. cipher wheel). Receives a container to render into. */
  visual?: (values: Record<string, string>, container: HTMLElement, ctx: ToolContext) => void;
}

const tools: Tool[] = [];

export function register(tool: Tool): void {
  if (tools.some((t) => t.id === tool.id)) {
    console.warn(`[CypherMiner] duplicate tool id ignored: ${tool.id}`);
    return;
  }
  tools.push(tool);
}

export function toolsByCategory(cat: CategoryId): Tool[] {
  return tools.filter((t) => t.category === cat);
}

