  return (v.text || '')
    .normalize('NFD')          // split accented chars into base + combining mark
    .replace(/\p{M}/gu, '')    // drop the combining marks
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, sep)
    .replace(/^[-_]+|[-_]+$/g, '');
}

function isPrime(n: bigint): boolean {
  if (n < 2n) return false;
  for (const p of [2n,3n,5n,7n,11n,13n,17n,19n,23n,29n,31n,37n]) if (n % p === 0n) return n === p;
  let d = n - 1n, s = 0n;
  while ((d & 1n) === 0n) { d >>= 1n; s++; }
  for (const a of [2n,3n,5n,7n,11n,13n,17n,19n,23n,29n,31n,37n]) {
    let x = powmod(a, d, n);
    if (x === 1n || x === n - 1n) continue;
    let ok = false;
    for (let i = 0n; i < s - 1n; i++) { x = mulmod(x, x, n); if (x === n - 1n) { ok = true; break; } }
    if (!ok) return false;
  }
  return true;
}
function factorize(n: bigint, out: bigint[]): void {
  if (n === 1n) return;
  if (isPrime(n)) { out.push(n); return; }
  const d = pollardRho(n);
  factorize(d, out); factorize(n / d, out);
}

