const scored = docs.map((d) => {
    let score = 0;
    for (const q of expanded) {            // query tokens + synonyms
      for (const [t, w] of d.weights) {
        if (matches(t, q)) {
          const idf = Math.log(1 + total / (df.get(t) || 1));
          // square the idf so rare, specific terms (e.g. "palindrome")
          // outweigh generic category words (e.g. "cipher").
          score += w * idf * idf;
        }
      }
    }
    if (!explicitOther && context?.toolId && d.id === context.toolId) score *= 1.3;
    return { id: d.id, score };
  })
  .filter((s) => s.score > 0)
  .sort((a, b) => b.score - a.score);

