export const cloudProvider: AssistantProvider = {
  id: 'cloud',
  async ask(query, lang, context) {
    const endpoint = getConfig().cloudEndpoint;
    if (!endpoint) throw new Error('Cloud assistant is not configured (set cloudEndpoint in config.json).');
    const res = await fetch(endpoint, { method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ query, lang, context }) });
    if (!res.ok) throw new Error('Assistant request failed');
    return await res.json();
  },
};

